class BBPETrainer:
    """Точный учебный тренер, хранящий каждый повторяющийся чанк один раз."""

    def __init__(self, num_merges: int):
        """Задаёт целое неотрицательное число шагов слияния."""
        if type(num_merges) is not int or num_merges < 0:
            raise ValueError("num_merges должен быть целым неотрицательным числом")
        self.num_merges = num_merges
        self.merges: MergeTable = {}

    @staticmethod
    def _weighted_pair_counts(
        unique_chunks: dict[str, list[int]], frequencies: dict[str, int]
    ) -> Counter[Pair]:
        """Считает пары по уникальным чанкам с весом, равным их кратности."""
        counts: Counter[Pair] = Counter()
        for chunk_text, ids in unique_chunks.items():
            frequency = frequencies[chunk_text]
            for pair in zip(ids[:-1], ids[1:]):
                counts[pair] += frequency
        return counts

    def train(self, text: str) -> "BBPETrainer":
        """Обучает таблицу слияний; равные частоты разрешаются порядком обхода корпуса."""
        frequencies: dict[str, int] = {}
        for chunk in PATTERN.findall(text):
            frequencies[chunk] = frequencies.get(chunk, 0) + 1

        # dict сохраняет порядок первого появления, а значит, и выбор при равных частотах.
        unique_chunks = {
            chunk: list(chunk.encode("utf-8")) for chunk in frequencies
        }
        self.merges = {}
        for merge_index in range(self.num_merges):
            counts = self._weighted_pair_counts(unique_chunks, frequencies)
            if not counts:
                break
            pair = max(counts, key=counts.get)
            new_id = 256 + merge_index
            for chunk, ids in unique_chunks.items():
                if len(ids) > 1:
                    unique_chunks[chunk] = merge_pair_in_chunk(ids, pair, new_id)
            self.merges[pair] = new_id
        return self

    def vocab_bytes(self) -> dict[int, bytes]:
        """Восстанавливает байты токенов по таблице слияний."""
        vocab = {token_id: bytes([token_id]) for token_id in range(256)}
        for (left, right), new_id in self.merges.items():
            vocab[new_id] = vocab[left] + vocab[right]
        return vocab

