class BBPETokenizer:
    """Прозрачный byte-level BPE encoder/decoder для обучения и тестов."""

    def __init__(self, merges: MergeTable):
        """Проверяет упорядоченную таблицу слияний и восстанавливает байтовый словарь."""
        if not isinstance(merges, dict):
            raise ValueError("merges must be an ordered dict")
        self.merges = dict(merges)
        self._vocab: dict[int, bytes] = {
            token_id: bytes([token_id]) for token_id in range(256)
        }
        for rank, (pair, new_id) in enumerate(self.merges.items()):
            if (not isinstance(pair, tuple) or len(pair) != 2
                    or any(type(x) is not int for x in (*pair, new_id))):
                raise ValueError("merge entries must contain integer IDs, not bools")
            left, right = pair
            if new_id != 256 + rank:
                raise ValueError("new IDs must be consecutive in merge order from 256")
            if left not in self._vocab or right not in self._vocab:
                raise ValueError(
                    f"merge {(left, right)} references an unknown earlier token"
                )
            if new_id in self._vocab:
                raise ValueError(f"duplicate token id: {new_id}")
            self._vocab[new_id] = self._vocab[left] + self._vocab[right]

    def __len__(self) -> int:
        """Возвращает размер словаря, включая 256 байтовых токенов."""
        return len(self._vocab)

    def vocab_bytes(self) -> dict[int, bytes]:
        """Возвращает копию словаря ID → байты, чтобы вызывающий код не менял оригинал."""
        return dict(self._vocab)

    def _encode_chunk(self, ids: list[int]) -> list[int]:
        """Кодирует один regex-чанк, каждый раз применяя минимальный доступный ранг."""
        while len(ids) > 1:
            best_pair: Pair | None = None
            best_rank: int | None = None
            for pair in zip(ids[:-1], ids[1:]):
                rank = self.merges.get(pair)
                if rank is not None and (best_rank is None or rank < best_rank):
                    best_pair = pair
                    best_rank = rank
            if best_pair is None or best_rank is None:
                break
            ids = merge_pair_in_chunk(ids, best_pair, best_rank)
        return ids

    def encode(self, text: str) -> list[int]:
        """Кодирует Unicode-текст по чанкам, выбирая наименьший ранг слияния."""
        out: list[int] = []
        for chunk in PATTERN.findall(text):
            out.extend(self._encode_chunk(list(chunk.encode("utf-8"))))
        return out

    def decode(self, ids: list[int], *, errors: str = "replace") -> str:
        """Объединяет байты токенов и декодирует UTF-8 с явной политикой ошибок."""
        if any(type(token_id) is not int for token_id in ids):
            raise ValueError("decode expects integer IDs, not bools or floats")
        try:
            raw = b"".join(self._vocab[token_id] for token_id in ids)
        except KeyError as exc:
            raise ValueError(f"unknown token id: {exc.args[0]}") from exc
        return raw.decode("utf-8", errors=errors)

    def to_dict(self) -> dict:
        """Представляет упорядоченную таблицу слияний в формате, совместимом с JSON."""
        return {
            "version": "bbpe-course-2",
            "merges": [
                [left, right, new_id]
                for (left, right), new_id in self.merges.items()
            ],
        }

    def to_json(self) -> str:
        """Сохраняет учебный токенизатор в детерминированный JSON."""
        return json.dumps(self.to_dict(), ensure_ascii=False)

    @classmethod
    def from_dict(cls, obj: dict) -> "BBPETokenizer":
        """Создаёт токенизатор из проверенной структуры данных JSON."""
        if not isinstance(obj, dict) or obj.get("version") not in (
            "bbpe-course-1", "bbpe-course-2"
        ):
            raise ValueError("unsupported serialized tokenizer version")
        rows = obj.get("merges")
        if not isinstance(rows, list):
            raise ValueError("serialized tokenizer has no merge list")
        merges = {}
        for row in rows:
            if (not isinstance(row, list) or len(row) != 3
                    or any(type(x) is not int for x in row)):
                raise ValueError("each merge must be a list of three integer IDs")
            left, right, new_id = row
            if (left, right) in merges:
                raise ValueError("duplicate merge pair")
            merges[left, right] = new_id
        return cls(merges)

    @classmethod
    def from_json(cls, payload: str) -> "BBPETokenizer":
        """Создаёт токенизатор из строки JSON."""
        return cls.from_dict(json.loads(payload))

def benchmark_bytes_per_second(fn, text: str, repeat: int = 3) -> float:
    """Возвращает лучшую скорость кодирования из повторов, в байтах UTF-8 в секунду."""
    if repeat <= 0:
        raise ValueError("repeat must be positive")
    best_seconds = math.inf
    for _ in range(repeat):
        start = time.perf_counter()
        fn(text)
        best_seconds = min(best_seconds, time.perf_counter() - start)
    return len(text.encode("utf-8")) / best_seconds

benchmark_text = corpus_ru + corpus_en
ours_bps = benchmark_bytes_per_second(full_tokenizer.encode, benchmark_text)
if hf_tokenizer is not None:
    hf_bps = benchmark_bytes_per_second(
        lambda text: hf_tokenizer.encode(text).ids, benchmark_text
    )
    print(
        f"скорость кодирования: учебный Python={ours_bps / 1e6:.2f} MB/s | "
        f"HF Rust={hf_bps / 1e6:.2f} MB/s | отношение={hf_bps / ours_bps:.1f}x"
    )
else:
    print(f"скорость кодирования: учебный Python={ours_bps / 1e6:.2f} MB/s | HF пропущен")
